        self.TAPER_PARAMETERS = TAPER_PARAMETERS  # type: Optional[List[float]]
        self.STEERING_AZIMUTH_DEG = STEERING_AZIMUTH_DEG  # type: float
        self.STEERING_ELEVATION_DEG = STEERING_ELEVATION_DEG  # type: float
        self.STEERING_CONE_DEG = STEERING_CONE_DEG  # type: float
        self.STEERING_CLOCK_DEG = STEERING_CLOCK_DEG  # type: float
