        self.PEAK_GAIN_DBI = PEAK_GAIN_DBI  # type: float
        self.GAIN_CUTS = GAIN_CUTS  # type: Optional[List[PAPGainCut.PAPGainCutT]]
        self.AZIMUTH_3DB_BEAMWIDTH_DEG = AZIMUTH_3DB_BEAMWIDTH_DEG  # type: float
        self.ELEVATION_3DB_BEAMWIDTH_DEG = ELEVATION_3DB_BEAMWIDTH_DEG  # type: float
        self.FIRST_SIDELOBE_LEVEL_DB = FIRST_SIDELOBE_LEVEL_DB  # type: float
        self.PEAK_SIDELOBE_LEVEL_DB = PEAK_SIDELOBE_LEVEL_DB  # type: float
        self.GRATING_LOBE_PRESENT = GRATING_LOBE_PRESENT  # type: bool
        self.GRATING_LOBE_AZIMUTH_DEG = GRATING_LOBE_AZIMUTH_DEG  # type: Optional[List[float]]
        self.GRATING_LOBE_ELEVATION_DEG = GRATING_LOBE_ELEVATION_DEG  # type: Optional[List[float]]
